import * as BunServices from "@effect/platform-bun/BunServices";
import { expect, it } from "@effect/vitest";
import {
  ByteSize,
  Cause,
  Effect,
  Exit,
  FileSystem,
  Layer,
  Option,
  PlatformError,
  Ref,
} from "effect";

import { checkDocsImportBoundaries } from "./check-import-boundaries.runtime.js";

const fault = PlatformError.badArgument({
  description: "TAXKIT_SECRET_SENTINEL",
  method: "controlled-fixture",
  module: "FileSystem",
});

// This fixture implements the native file-information contract, not a second DTO.
const fileInfo: FileSystem.File.Info = {
  atime: Option.none(),
  birthtime: Option.none(),
  blksize: Option.none(),
  blocks: Option.none(),
  dev: 0,
  gid: Option.none(),
  ino: Option.none(),
  mode: 0o644,
  mtime: Option.none(),
  nlink: Option.some(1),
  rdev: Option.none(),
  size: ByteSize.bytes(0),
  type: "File",
  uid: Option.none(),
};

it.effect(
  "keeps browser-safe imports and excludes server, test and generated owners",
  () =>
    Effect.gen(function* () {
      const reads = yield* Ref.make<readonly string[]>([]);
      yield* checkDocsImportBoundaries("/fixture/docs").pipe(
        Effect.provide(
          Layer.merge(
            BunServices.layer,
            FileSystem.layerNoop({
              exists: () => Effect.succeed(false),
              readDirectory: () =>
                Effect.succeed([
                  "lib/browser.ts",
                  "lib/source.server.ts",
                  "lib/source.server.tsx",
                  "lib/source.test.ts",
                  "server.ts",
                  "routeTree.gen.ts",
                  "asset.svg",
                  "subfolder",
                  "directory.ts",
                  ".hidden.ts",
                  "lib/.private/source.ts",
                ]),
              readFileString: (path) =>
                Ref.update(reads, (paths) => [...paths, path]).pipe(
                  Effect.as(
                    'export { DocsPagePath } from "@taxkit/docs-content/schemas";'
                  )
                ),
              stat: (path) =>
                Effect.succeed(
                  path.endsWith("directory.ts")
                    ? { ...fileInfo, type: "Directory" }
                    : fileInfo
                ),
            })
          )
        )
      );
      expect(yield* Ref.get(reads)).toEqual([
        "/fixture/docs/src/lib/browser.ts",
      ]);
    })
);

it.effect.each([
  'import { service } from "@taxkit/docs-content/service";',
  'export { live } from "@taxkit/docs-fumadocs/live";',
  'import { runtime } from "#/lib/runtime.server";',
  'import { runtime } from "./runtime.server";',
  "Effect.runPromise(program);",
  "ManagedRuntime.make(layer);",
])("rejects a direct browser reference: %s", (source) =>
  Effect.gen(function* () {
    const exit = yield* checkDocsImportBoundaries("/fixture/docs").pipe(
      Effect.provide(
        Layer.merge(
          BunServices.layer,
          FileSystem.layerNoop({
            exists: () => Effect.succeed(false),
            readDirectory: () => Effect.succeed(["lib/browser.ts"]),
            readFileString: () => Effect.succeed(source),
            stat: () => Effect.succeed(fileInfo),
          })
        )
      ),
      Effect.exit
    );
    expect(Exit.isFailure(exit)).toBe(true);
    if (Exit.isFailure(exit)) {
      expect(Cause.pretty(exit.cause)).toContain("DocsImportPolicyError");
    }
  })
);

it.effect("rejects a browser runtime file even if it is empty", () =>
  Effect.gen(function* () {
    const exit = yield* checkDocsImportBoundaries("/fixture/docs").pipe(
      Effect.provide(
        Layer.merge(
          BunServices.layer,
          FileSystem.layerNoop({
            exists: () => Effect.succeed(true),
            readDirectory: () => Effect.succeed([]),
            stat: () => Effect.succeed(fileInfo),
          })
        )
      ),
      Effect.exit
    );
    expect(Exit.isFailure(exit)).toBe(true);
    if (Exit.isFailure(exit)) {
      expect(Cause.pretty(exit.cause)).toContain("DocsImportPolicyError");
    }
  })
);

it.effect.each([
  "source-list",
  "source-stat",
  "source-file",
  "browser-runtime",
])("fails closed and hides native source details: %s", (operation) =>
  Effect.gen(function* () {
    const exit = yield* checkDocsImportBoundaries("/fixture/docs").pipe(
      Effect.provide(
        Layer.merge(
          BunServices.layer,
          FileSystem.layerNoop({
            exists: () =>
              operation === "browser-runtime"
                ? Effect.fail(fault)
                : Effect.succeed(false),
            readDirectory: () =>
              operation === "source-list"
                ? Effect.fail(fault)
                : Effect.succeed(["lib/browser.ts"]),
            readFileString: () =>
              operation === "source-file"
                ? Effect.fail(fault)
                : Effect.succeed("export {};"),
            stat: () =>
              operation === "source-stat"
                ? Effect.fail(fault)
                : Effect.succeed(fileInfo),
          })
        )
      ),
      Effect.exit
    );
    expect(Exit.isFailure(exit)).toBe(true);
    if (Exit.isFailure(exit)) {
      expect(Cause.pretty(exit.cause)).toContain("DocsImportReadError");
      expect(Cause.pretty(exit.cause)).not.toContain("TAXKIT_SECRET_SENTINEL");
      expect(Cause.findErrorOption(exit.cause)).toMatchObject({
        value: { operation },
      });
    }
  })
);

import * as BunRuntime from "@effect/platform-bun/BunRuntime";
import * as BunServices from "@effect/platform-bun/BunServices";
import ts from "@typescript/typescript6";
import {
  Array,
  Console,
  Effect,
  FileSystem,
  Match,
  Path,
  Schema,
} from "effect";

class DocsImportReadError extends Schema.TaggedError<DocsImportReadError>()(
  "DocsImportReadError",
  {
    operation: Schema.Literals([
      "app-root",
      "source-list",
      "source-file",
      "source-stat",
      "browser-runtime",
    ]),
  }
) {}
class DocsImportPolicyError extends Schema.TaggedError<DocsImportPolicyError>()(
  "DocsImportPolicyError",
  { failures: Schema.Array(Schema.String) }
) {}

const serverOnlyModulePattern =
  /(?:@taxkit\/docs-content\/(?:generated-source|live|server|service|test|validate)|@taxkit\/docs-fumadocs\/(?:live|service|test)|#\/lib\/runtime\.server|\.\/runtime\.server)/u;
const runtimeExecutionPattern =
  /\b(?:ManagedRuntime|Runtime)\.|\bEffect\.run(?:Fork|Promise|PromiseExit|Sync)\b/u;

export const checkDocsImportBoundaries = (appRoot: string) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const sourceRoot = path.join(appRoot, "src");
    const paths = yield* fs
      .readDirectory(sourceRoot, { recursive: true })
      .pipe(
        Effect.mapError(
          () => new DocsImportReadError({ operation: "source-list" })
        )
      );
    const browserPaths = Array.filter(
      paths,
      (relativePath) =>
        /\.(?:js|jsx|ts|tsx)$/u.test(relativePath) &&
        !Array.some(relativePath.split(path.sep), (segment) =>
          segment.startsWith(".")
        ) &&
        !relativePath.endsWith(".server.ts") &&
        !relativePath.endsWith(".server.tsx") &&
        !relativePath.includes(".test.") &&
        relativePath !== "server.ts" &&
        relativePath !== "routeTree.gen.ts"
    );
    const findings = yield* Effect.forEach(browserPaths, (relativePath) =>
      fs.stat(path.join(sourceRoot, relativePath)).pipe(
        Effect.mapError(
          () => new DocsImportReadError({ operation: "source-stat" })
        ),
        Effect.flatMap((info) =>
          info.type === "File"
            ? fs.readFileString(path.join(sourceRoot, relativePath)).pipe(
                Effect.mapError(
                  () => new DocsImportReadError({ operation: "source-file" })
                ),
                Effect.map((source) => {
                  // TypeScript owns this parser and its checked AST node predicates.
                  // This checks direct static references, separately from bundle proof.
                  const sourceFile = ts.createSourceFile(
                    relativePath,
                    source,
                    ts.ScriptTarget.Latest,
                    true
                  );
                  const imports = Array.flatMap(
                    sourceFile.statements,
                    (statement) =>
                      (ts.isImportDeclaration(statement) ||
                        ts.isExportDeclaration(statement)) &&
                      statement.moduleSpecifier !== undefined &&
                      ts.isStringLiteral(statement.moduleSpecifier) &&
                      serverOnlyModulePattern.test(
                        statement.moduleSpecifier.text
                      )
                        ? [
                            `${relativePath} statically imports a server-only docs module: ${statement.moduleSpecifier.text}`,
                          ]
                        : []
                  );
                  return runtimeExecutionPattern.test(source)
                    ? Array.append(
                        imports,
                        `${relativePath} executes an Effect runtime from browser-reachable source.`
                      )
                    : imports;
                })
              )
            : Effect.succeed([])
        )
      )
    );
    const hasBrowserRuntime = yield* fs
      .exists(path.join(sourceRoot, "lib/runtime.client.ts"))
      .pipe(
        Effect.mapError(
          () => new DocsImportReadError({ operation: "browser-runtime" })
        )
      );
    const failures = hasBrowserRuntime
      ? Array.append(
          Array.flatten(findings),
          "The docs app must not own a browser Effect runtime at src/lib/runtime.client.ts."
        )
      : Array.flatten(findings);
    return yield* Match.value(failures.length).pipe(
      Match.when(0, () =>
        Console.info("Docs server/browser import boundaries passed.")
      ),
      Match.orElse(() => Effect.fail(new DocsImportPolicyError({ failures })))
    );
  });

if (import.meta.main) {
  BunRuntime.runMain(
    Effect.gen(function* () {
      const path = yield* Path.Path;
      const appRoot = yield* path
        .fromFileUrl(new URL("..", import.meta.url))
        .pipe(
          Effect.mapError(
            () => new DocsImportReadError({ operation: "app-root" })
          )
        );
      yield* checkDocsImportBoundaries(appRoot);
    }).pipe(
      Effect.tapErrorTag("DocsImportPolicyError", (error) =>
        Effect.forEach(error.failures, Console.error)
      ),
      Effect.provide(BunServices.layer)
    )
  );
}

import * as BunHttpServer from "@effect/platform-bun/BunHttpServer";
import * as BunServices from "@effect/platform-bun/BunServices";
import { expect, it } from "@effect/vitest";
import {
  Array,
  Config,
  Deferred,
  Effect,
  Fiber,
  FileSystem,
  Layer,
  Match,
  Option,
  Path,
  Ref,
  Result,
  Schema,
  Stream,
} from "effect";
import {
  Headers,
  HttpServer,
  HttpServerRequest,
  HttpServerResponse,
} from "effect/http";

import { verifyBuiltBrowser } from "./cloudflare-built-browser.live.js";
import {
  BuiltBrowserInput,
  BuiltProofError,
} from "./cloudflare-built-proof.boundary.js";

const title = "Calculate Australian take-home pay";
const script = `
const main=document.querySelector("main");
const article='<article class="docs-article"><h1>Calculate Australian take-home pay</h1><p>Controlled browser fixture.</p></article>';
main.dataset.tkHydrated="true";
main.dataset.tkNavigationInteractive="true";
window.__TSR_ROUTER__={navigate:({to})=>{
  if(to.includes("missing")){main.innerHTML='<div data-testid="route-not-found">Documentation page not found</div>';return Promise.resolve()}
  main.innerHTML='<div class="docs-route-state" data-testid="route-pending"><h1>Loading documentation</h1><p>Loading fixture.</p></div>';
  return fetch("/_serverFn/guide").then(()=>{main.innerHTML=article;const late=document.createElement("script");late.src="/assets/late-ABC123xy.js";document.head.append(late)})
}};
document.querySelector("#reference").addEventListener("click",event=>{event.preventDefault();fetch("/_serverFn/reference").then(()=>{main.innerHTML='<h1>Reference</h1>'})});
document.querySelector("#skip").addEventListener("click",event=>{event.preventDefault();main.focus()});
document.querySelector("#mobile").addEventListener("click",event=>{event.currentTarget.setAttribute("aria-label","Close navigation");event.currentTarget.setAttribute("aria-expanded","true")});
`;
const html = `<html><head><style>:root,.docs-nav-toggle{background:rgb(255,255,255)}body,.docs-article p,.docs-route-state p,.docs-nav-toggle{color:rgb(0,0,0)}*{animation-name:none;transition-duration:0s}</style><script defer src="/assets/route-ABC123xy.js"></script></head><body><a id="skip" href="#docs-main">Skip to documentation</a><nav aria-label="Documentation"><a id="reference" href="/reference">Reference</a><a href="/guides/calculate-australian-take-home-pay">Calculate Australian take-home pay</a></nav><button class="docs-nav-toggle" id="mobile" aria-label="Open navigation">Menu</button><main id="docs-main" tabindex="-1"><article class="docs-article"><h1>${title}</h1><p>Controlled browser fixture.</p></article></main></body></html>`;

it.live.each([
  {
    mode: "clean",
    name: "checks malformed JSON and delayed navigation with late assets, screenshots and cleanup",
  },
  {
    mode: "clean-no-screenshots",
    name: "keeps late script assets outside delayed RPC routing without screenshot timing",
  },
  {
    mode: "private-console",
    name: "rejects private console output without copying it into the safe error",
  },
  {
    mode: "overflow",
    name: "fails closed when the real Chromium event queue overflows",
  },
] as const)(
  "$name",
  ({ mode }) =>
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const screenshotDirectory = yield* fs.makeTempDirectoryScoped();
      const requests = yield* Ref.make<readonly string[]>([]);
      const malformedBodies = yield* Ref.make<readonly string[]>([]);
      const server = yield* HttpServer.HttpServer;
      yield* server.serve(
        Effect.gen(function* () {
          const request = yield* HttpServerRequest.HttpServerRequest;
          yield* Ref.update(requests, (values) =>
            Array.append(values, `${request.method} ${request.url}`)
          );
          if (request.url === "/assets/route-ABC123xy.js") {
            const diagnostics = Match.value(mode).pipe(
              Match.when(
                "private-console",
                () => 'console.error("private-fixture-value");'
              ),
              Match.when(
                "overflow",
                () =>
                  'for(let count=0;count<1100;count++){console.warn("overflow-fixture")}'
              ),
              Match.whenOr("clean", "clean-no-screenshots", () => ""),
              Match.exhaustive
            );
            return HttpServerResponse.text(`${script}\n${diagnostics}`, {
              contentType: "text/javascript",
            });
          }
          if (request.url === "/assets/late-ABC123xy.js") {
            return HttpServerResponse.text("/* late fixture asset */", {
              contentType: "text/javascript",
            });
          }
          if (request.url.startsWith("/_serverFn/")) {
            const body = request.method === "POST" ? yield* request.text : "";
            if (request.method === "POST") {
              yield* Ref.update(malformedBodies, (values) =>
                Array.append(values, body)
              );
            }
            return HttpServerResponse.text("fixture", {
              status:
                request.method === "POST" &&
                body === "{" &&
                Headers.get(request.headers, "content-type").pipe(
                  Option.contains("application/json")
                )
                  ? 400
                  : 200,
            });
          }
          if (request.url === "/favicon.ico") {
            return HttpServerResponse.empty({ status: 204 });
          }
          return HttpServerResponse.text(html, { contentType: "text/html" });
        })
      );
      const input = yield* Schema.decodeEffect(BuiltBrowserInput)({
        captureScreenshots: mode === "clean",
        environment: {
          PATH: yield* Config.String("PATH"),
          PLAYWRIGHT_BROWSERS_PATH: yield* Config.String(
            "PLAYWRIGHT_BROWSERS_PATH"
          ),
        },
        origin: HttpServer.formatAddress(server.address),
        screenshotDirectory,
      });
      const result = yield* verifyBuiltBrowser(input).pipe(Effect.result);
      if (mode === "clean" || mode === "clean-no-screenshots") {
        expect(yield* Ref.get(malformedBodies)).toEqual(["{"]);
        const observation = yield* Effect.fromResult(result);
        expect(observation.serverFunctionRequests).toBe(2);
        expect(
          Array.map(observation.screenshots, (screenshot) => screenshot.kind)
        ).toEqual(mode === "clean" ? ["desktop", "mobile"] : []);
        yield* Effect.forEach(observation.screenshots, (screenshot) =>
          Effect.gen(function* () {
            expect(
              Number(
                (yield* fs.stat(
                  path.join(
                    screenshotDirectory,
                    screenshot.path.replace("screenshots/", "")
                  )
                )).size
              )
            ).toBeGreaterThan(0);
          })
        );
        expect(yield* Ref.get(requests)).toContain("GET /_serverFn/guide");
      } else {
        expect(result).toEqual(
          Result.fail(
            new BuiltProofError({
              operation: "browser",
              reason: "start-or-read",
            })
          )
        );
      }
    }).pipe(
      Effect.provide(
        Layer.mergeAll(
          BunServices.layer,
          BunHttpServer.layer({ hostname: "127.0.0.1", port: 0 })
        )
      )
    ),
  15_000
);

it.live(
  "interrupting a real pending browser response closes Chromium and retires the request",
  () =>
    Effect.gen(function* () {
      const started = yield* Deferred.make<boolean>();
      const retired = yield* Deferred.make<boolean>();
      const fs = yield* FileSystem.FileSystem;
      const screenshotDirectory = yield* fs.makeTempDirectoryScoped();
      const server = yield* HttpServer.HttpServer;
      yield* server.serve(
        Effect.succeed(
          HttpServerResponse.stream(
            Stream.concat(
              Stream.succeed(new TextEncoder().encode("<html><body>")),
              Stream.fromEffect(
                Deferred.succeed(started, true).pipe(
                  Effect.andThen(Effect.never),
                  Effect.onInterrupt(() => Deferred.succeed(retired, true))
                )
              )
            ),
            { contentType: "text/html" }
          )
        )
      );
      const input = yield* Schema.decodeEffect(BuiltBrowserInput)({
        captureScreenshots: false,
        environment: {
          PATH: yield* Config.String("PATH"),
          PLAYWRIGHT_BROWSERS_PATH: yield* Config.String(
            "PLAYWRIGHT_BROWSERS_PATH"
          ),
        },
        origin: HttpServer.formatAddress(server.address),
        screenshotDirectory,
      });
      const fiber = yield* verifyBuiltBrowser(input).pipe(
        Effect.scoped,
        Effect.forkChild({ startImmediately: true })
      );
      expect(yield* Deferred.await(started)).toBe(true);
      yield* Fiber.interrupt(fiber);
      expect(
        yield* Deferred.await(retired).pipe(Effect.timeout("5 seconds"))
      ).toBe(true);
    }).pipe(
      Effect.provide(
        Layer.mergeAll(
          BunServices.layer,
          BunHttpServer.layer({ hostname: "127.0.0.1", port: 0 })
        )
      )
    ),
  10_000
);

import {
  Array as EffectArray,
  Crypto,
  Effect,
  Fiber,
  FileSystem,
  Match,
  Option,
  Path,
  Queue,
  Ref,
  Schema,
  Stream,
} from "effect";
import { Hex } from "effect/encoding";
import { chromium } from "playwright";
import type {
  ConsoleMessage,
  Page,
  Request,
  Response as BrowserResponse,
  Route,
} from "playwright";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";

import { DocsRecoverableError } from "../src/components/docs-route-states.js";
import type { BuiltBrowserInput } from "./cloudflare-built-proof.boundary.js";
import {
  BuiltBrowserObservation,
  BuiltProofError,
} from "./cloudflare-built-proof.boundary.js";
import { HostedProofSha256 } from "./cloudflare-hosted-proof.boundary.js";

const knownPath = "/guides/calculate-australian-take-home-pay";
const missingPath = "/__docs-evidence__/missing";
const browserFailure = () =>
  new BuiltProofError({ operation: "browser", reason: "start-or-read" });
// These are proof assertions, not operational exceptions containing SDK data.
const requireProof = (passes: boolean) =>
  passes ? Effect.void : Effect.fail(browserFailure());

const ServerFunctionObservation = Schema.Struct({
  kind: Schema.Literal("server-function"),
  method: Schema.String,
  status: Schema.Int,
  url: Schema.String,
});
const BrowserEvent = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("diagnostic"), text: Schema.String }),
  Schema.Struct({ kind: Schema.Literal("document") }),
  Schema.Struct({ kind: Schema.Literal("transport-request") }),
  Schema.Struct({ kind: Schema.Literal("missing-asset") }),
  ServerFunctionObservation,
]);
const BrowserObservations = Schema.Struct({
  diagnostics: Schema.Array(Schema.String),
  documentRequests: Schema.Int,
  missingScriptAsset: Schema.Boolean,
  serverFunctions: Schema.Array(ServerFunctionObservation),
  transportRequests: Schema.Int,
});

const isExpectedServerFunctionAbort = (request: Request, origin: string) =>
  (request.resourceType() === "fetch" || request.resourceType() === "xhr") &&
  request.url().startsWith(`${origin}/_serverFn/`) &&
  request.failure()?.errorText === "net::ERR_ABORTED";

// The SDK callbacks can only enqueue observations. They never execute an
// Effect, change application arrays or expose the Page outside this adapter.
const observePage = Effect.fnUntraced(function* (page: Page, origin: string) {
  const events = yield* Queue.make<typeof BrowserEvent.Type>({
    capacity: 1024,
    strategy: "dropping",
  });
  const overflow = yield* Queue.make<boolean>({
    capacity: 1,
    strategy: "dropping",
  });
  const observations = yield* Ref.make<typeof BrowserObservations.Type>({
    diagnostics: [],
    documentRequests: 0,
    missingScriptAsset: false,
    serverFunctions: [],
    transportRequests: 0,
  });
  const enqueue = (event: typeof BrowserEvent.Type) => {
    if (!Queue.offerUnsafe(events, event)) {
      Queue.offerUnsafe(overflow, true);
    }
  };
  // Listener types come from the installed SDK's event contract.
  const onConsole = (message: ConsoleMessage) => {
    if (message.type() === "error" || message.type() === "warning") {
      enqueue({
        kind: "diagnostic",
        text: `${message.type()}: ${message.text()}`,
      });
    }
  };
  const onError = (error: Error) =>
    enqueue({ kind: "diagnostic", text: `pageerror: ${error.message}` });
  const onFailed = (request: Request) => {
    if (!isExpectedServerFunctionAbort(request, origin)) {
      enqueue({
        kind: "diagnostic",
        text: `requestfailed: ${request.url()} ${request.failure()?.errorText ?? ""}`,
      });
    }
  };
  const onRequest = (request: Request) => {
    if (request.resourceType() === "document") {
      enqueue({ kind: "document" });
    }
    if (
      request.resourceType() === "fetch" ||
      request.resourceType() === "xhr"
    ) {
      enqueue({ kind: "transport-request" });
    }
  };
  const onResponse = (response: BrowserResponse) => {
    const request = response.request();
    if (
      response.status() === 404 &&
      response.url().startsWith(origin) &&
      /^\/assets\/[^/?#]+-[A-Za-z0-9_-]{8,}\.js$/u.test(
        response.url().slice(origin.length)
      )
    ) {
      enqueue({ kind: "missing-asset" });
    }
    if (
      (request.resourceType() === "fetch" ||
        request.resourceType() === "xhr") &&
      response.url().includes("/_serverFn/")
    ) {
      enqueue({
        kind: "server-function",
        method: request.method(),
        status: response.status(),
        url: response.url(),
      });
    }
  };
  yield* Effect.acquireRelease(
    Effect.sync(() => {
      page.on("console", onConsole);
      page.on("pageerror", onError);
      page.on("requestfailed", onFailed);
      page.on("request", onRequest);
      page.on("response", onResponse);
    }),
    () =>
      Effect.sync(() => {
        page.off("console", onConsole);
        page.off("pageerror", onError);
        page.off("requestfailed", onFailed);
        page.off("request", onRequest);
        page.off("response", onResponse);
      })
  );
  const collect = Effect.gen(function* () {
    yield* requireProof((yield* Queue.size(overflow)) === 0);
    const incoming = yield* Queue.clear(events);
    return yield* Ref.updateAndGet(observations, (state) =>
      EffectArray.reduce(incoming, state, (current, observedEvent) =>
        Match.value(observedEvent).pipe(
          Match.when({ kind: "diagnostic" }, (event) => ({
            ...current,
            diagnostics: EffectArray.append(current.diagnostics, event.text),
          })),
          Match.when({ kind: "document" }, () => ({
            ...current,
            documentRequests: current.documentRequests + 1,
          })),
          Match.when({ kind: "transport-request" }, () => ({
            ...current,
            transportRequests: current.transportRequests + 1,
          })),
          Match.when({ kind: "missing-asset" }, () => ({
            ...current,
            missingScriptAsset: true,
          })),
          Match.when({ kind: "server-function" }, (event) => ({
            ...current,
            serverFunctions: EffectArray.append(current.serverFunctions, event),
          })),
          Match.exhaustive
