import { describe, expect, it as test } from "@effect/vitest";
import {
  createMemoryHistory,
  createRootRoute,
  createRoute,
  createRouter,
  notFound,
  Outlet,
  RouterProvider,
} from "@tanstack/react-router";
import type { ErrorComponentProps } from "@tanstack/react-router";
import { DocsSourceError } from "@taxkit/docs-content/errors";
import { DocsNavigation, DocsSourcePath } from "@taxkit/docs-content/schemas";
import { Effect, Match, Result } from "effect";
import { flushSync } from "react-dom";
import { createRoot } from "react-dom/client";
import { vi } from "vitest";

import { DocsContentPreloadError } from "#/lib/docs/errors";
import { docsHomeRouteBoundary } from "#/lib/docs/route-boundary";

const homeSuccess = {
  navigation: DocsNavigation.make({
    contentRoot: "packages/docs-content/content",
    primaryNavigation: [],
    status: "published",
  }),
  pages: [],
};

const rootRoute = createRootRoute({ component: Outlet });

const FrameworkError = ({ error }: ErrorComponentProps) => (
  <div data-error={String(error)} data-testid="framework-loader-error" />
);

const harnessRoute = createRoute({
  getParentRoute: () => rootRoute,
  // This is the single fake server-loader bridge required by the Router host.
  // Native test bodies below do not execute an Effect runtime.
  loader: ({ params }) =>
    Effect.runPromise(
      Match.value(params.scenario).pipe(
        Match.when("success", () =>
          docsHomeRouteBoundary.encodeExit(Effect.succeed(homeSuccess))
        ),
        Match.when("preload-error", () =>
          docsHomeRouteBoundary.encodeExit(
            Effect.fail(
              new DocsContentPreloadError({
                message: "Unable to preload docs content",
                path: DocsSourcePath.make("content/start/index.mdx"),
              })
            )
          )
        ),
        Match.when("not-found-error", () => Effect.die(notFound())),
        Match.when("source-error", () =>
          docsHomeRouteBoundary.encodeExit(
            Effect.fail(
              new DocsSourceError({
                message: "The docs source failed.",
                operation: "getPage",
              })
            )
          )
        ),
        Match.when("malformed", () => Effect.succeed({ malformed: true })),
        Match.when("defect", () =>
          docsHomeRouteBoundary.encodeExit(
            Effect.die(new Error("fatal docs loader defect"))
          )
        ),
        Match.when("interruption", () =>
          docsHomeRouteBoundary.encodeExit(Effect.interrupt)
        ),
        Match.orElse((scenario) =>
          docsHomeRouteBoundary.encodeExit(
            Effect.die(new Error(`Unknown browser scenario: ${scenario}`))
          )
        )
      )
    ),
  path: "/$scenario",
});

const HarnessRoute = () => {
  const loaderData = harnessRoute.useLoaderData();
  const routeResult = docsHomeRouteBoundary.restore(loaderData);

  return Result.match(routeResult, {
    onFailure: (error) =>
      Match.value(error).pipe(
        Match.tags({
          DocsContentPreloadError: ({ _tag }) => (
            <div data-testid="expected-loader-error">{_tag}</div>
          ),
          DocsRouteTransportError: ({ _tag }) => (
            <div data-testid="transport-loader-error">{_tag}</div>
          ),
          DocsSourceError: ({ _tag }) => (
            <div data-testid="expected-loader-error">{_tag}</div>
          ),
        }),
        Match.exhaustive
      ),
    onSuccess: () => <div data-testid="loader-success">Docs loaded</div>,
  });
};

const routeTree = rootRoute.addChildren([
  harnessRoute.update({
    component: HarnessRoute,
    errorComponent: FrameworkError,
    notFoundComponent: () => (
      <div data-testid="framework-not-found">Not found</div>
    ),
  }),
]);

const nextAnimationFrame = Effect.callback((resume) => {
  const frame = requestAnimationFrame(() => {
    resume(Effect.void);
  });

  return Effect.sync(() => cancelAnimationFrame(frame));
});

const createHarnessRouter = (path: string) =>
  createRouter({
    history: createMemoryHistory({ initialEntries: [path] }),
    routeTree,
  });

type HarnessRender = Readonly<{
  consoleError: ReturnType<typeof vi.spyOn>;
  consoleWarn: ReturnType<typeof vi.spyOn>;
  host: HTMLDivElement;
  root: ReturnType<typeof createRoot>;
  router: ReturnType<typeof createHarnessRouter>;
}>;

const acquireRenderedHarnessRoute = (path: string) =>
  Effect.gen(function* () {
    const host = yield* Effect.acquireRelease(
      Effect.sync(() => {
        const element = document.createElement("div");
        document.body.replaceChildren(element);
        return element;
      }),
      (element) => Effect.sync(() => element.remove())
    );
    const consoleError = yield* Effect.acquireRelease(
      Effect.sync(() =>
        vi.spyOn(console, "error").mockImplementation(() => {})
      ),
      (spy) => Effect.sync(() => spy.mockRestore())
    );
    const consoleWarn = yield* Effect.acquireRelease(
      Effect.sync(() => vi.spyOn(console, "warn").mockImplementation(() => {})),
      (spy) => Effect.sync(() => spy.mockRestore())
    );
    const root = yield* Effect.acquireRelease(
      Effect.sync(() => createRoot(host, { onCaughtError: () => {} })),
      (reactRoot) => Effect.sync(() => reactRoot.unmount())
    );
    const router = yield* Effect.acquireRelease(
      Effect.sync(() => createHarnessRouter(path)),
      (harnessRouter) => Effect.sync(() => harnessRouter.history.destroy())
    );
    yield* Effect.promise(() => router.load());
    yield* Effect.sync(() =>
      flushSync(() => root.render(<RouterProvider router={router} />))
    );
    yield* nextAnimationFrame;
    return {
      consoleError,
      consoleWarn,
      host,
      root,
      router,
    } satisfies HarnessRender;
  });

const expectCleanConsole = ({
  consoleError,
  consoleWarn,
}: Pick<HarnessRender, "consoleError" | "consoleWarn">) => {
  expect(consoleError).not.toHaveBeenCalled();
  expect(consoleWarn).not.toHaveBeenCalled();
};

describe("docs route boundary browser harness", () => {
  test.effect("renders success after direct route-root restoration", () =>
    Effect.gen(function* () {
      const render = yield* acquireRenderedHarnessRoute("/success");
      expect(
        render.host.querySelector('[data-testid="loader-success"]')
      ).toHaveProperty("textContent", "Docs loaded");
      expectCleanConsole(render);
    }).pipe(Effect.scoped)
  );

  test.effect.each([
    ["preload-error", "DocsContentPreloadError"],
    ["source-error", "DocsSourceError"],
  ] as const)(
    "renders the %s expected failure in route UI",
    ([scenario, tag]) =>
      Effect.gen(function* () {
        const render = yield* acquireRenderedHarnessRoute(`/${scenario}`);
        expect(
          render.host.querySelector('[data-testid="expected-loader-error"]')
        ).toHaveProperty("textContent", tag);
        expect(
          render.host.querySelector('[data-testid="framework-loader-error"]')
        ).toBeNull();
        expectCleanConsole(render);
      }).pipe(Effect.scoped)
  );

  test.effect("routes missing pages to the TanStack not-found component", () =>
    Effect.gen(function* () {
      const render = yield* acquireRenderedHarnessRoute("/not-found-error");
      expect(
        render.host.querySelector('[data-testid="framework-not-found"]')
      ).toHaveProperty("textContent", "Not found");
      expect(
        render.host.querySelector('[data-testid="expected-loader-error"]')
      ).toBeNull();
      expectCleanConsole(render);
    }).pipe(Effect.scoped)
  );

  test.effect("renders malformed transport in route UI", () =>
    Effect.gen(function* () {
      const render = yield* acquireRenderedHarnessRoute("/malformed");
      expect(
        render.host.querySelector('[data-testid="transport-loader-error"]')
      ).toHaveProperty("textContent", "DocsRouteTransportError");
      expect(
        render.host.querySelector('[data-testid="framework-loader-error"]')
      ).toBeNull();
      expectCleanConsole(render);
    }).pipe(Effect.scoped)
  );

  test.effect.each(["defect", "interruption"] as const)(
    "routes %s rejection to the TanStack error component",
    (scenario) =>
      Effect.gen(function* () {
        const render = yield* acquireRenderedHarnessRoute(`/${scenario}`);
        expect(
          render.host.querySelector('[data-testid="framework-loader-error"]')
        ).not.toBeNull();
        expect(
          render.host.querySelector('[data-testid="loader-success"]')
        ).toBeNull();
        expect(render.consoleError).not.toHaveBeenCalled();
        expect(render.consoleWarn.mock.calls).toEqual([
          [`Warning: Error in route match: /$scenario/${scenario}`],
        ]);
      }).pipe(Effect.scoped)
  );
});

import { describe, expect, it as test } from "@effect/vitest";
import { DocsSourceError } from "@taxkit/docs-content/errors";
import { DocsNavigation, DocsSourcePath } from "@taxkit/docs-content/schemas";
import { Cause, Effect, Equal, Exit, Result, Schema } from "effect";

import { DocsContentPreloadError, DocsRouteTransportError } from "./errors";
import { docsHomeRouteBoundary } from "./route-boundary";

const homeSuccess = {
  navigation: DocsNavigation.make({
    contentRoot: "packages/docs-content/content",
    primaryNavigation: [],
    status: "published",
  }),
  pages: [],
} as const;

const expectedErrors = [
  new DocsContentPreloadError({
    message: "Unable to preload content",
    path: DocsSourcePath.make("content/start.mdx"),
  }),
  new DocsSourceError({
    message: "The docs source failed.",
    operation: "getPage",
  }),
] as const;

const encodeHomeExit = Schema.encodeEffect(docsHomeRouteBoundary.codec);
const encodeUntrustedDefectExit = Schema.encodeEffect(
  Schema.toCodecJson(
    Schema.Exit(Schema.Unknown, Schema.Unknown, Schema.Defect())
  )
);

describe("docs route boundary", () => {
  test.effect(
    "round-trips canonical success through the encoded representation",
    () =>
      Effect.gen(function* () {
        const encoded = yield* docsHomeRouteBoundary.encodeExit(
          Effect.succeed(homeSuccess)
        );
        const result = docsHomeRouteBoundary.restore(encoded);

        expect(Result.isSuccess(result)).toBe(true);
        if (Result.isSuccess(result)) {
          expect(result.success).toEqual(homeSuccess);
        }
      })
  );

  test.effect("round-trips every expected docs failure", () =>
    Effect.forEach(
      expectedErrors,
      (error) =>
        Effect.gen(function* () {
          const encoded = yield* docsHomeRouteBoundary.encodeExit(
            Effect.fail(error)
          );
          const result = docsHomeRouteBoundary.restore(encoded);
          expect(Result.isFailure(result)).toBe(true);
          if (Result.isFailure(result)) {
            expect(result.failure._tag).toBe(error._tag);
          }
        }),
      { concurrency: 4 }
    )
  );

  test("maps malformed transport to the canonical transport error", () => {
    const result = docsHomeRouteBoundary.restore({ malformed: true });
    expect(Result.isFailure(result)).toBe(true);
    if (Result.isFailure(result)) {
      expect(Schema.is(DocsRouteTransportError)(result.failure)).toBe(true);
    }
  });

  test.effect(
    "preserves standalone and composite defects and interruptions",
    () =>
      Effect.gen(function* () {
        const expectedFailure = new DocsSourceError({
          message: "Expected source failure",
          operation: "getPage",
        });
        const causes = [
          Cause.die(new Error("standalone defect")),
          Cause.interrupt(101),
          Cause.combine(
            Cause.fail(expectedFailure),
            Cause.die(new Error("composite defect"))
          ),
          Cause.combine(Cause.fail(expectedFailure), Cause.interrupt(102)),
        ];

        yield* Effect.forEach(
          causes,
          (cause) =>
            Effect.gen(function* () {
              const exit = yield* Effect.exit(
                docsHomeRouteBoundary.encodeExit(Effect.failCause(cause))
              );
              expect(Exit.isFailure(exit)).toBe(true);
              if (Exit.isFailure(exit)) {
                expect(Equal.equals(exit.cause, cause)).toBe(true);
              }
            }),
          { concurrency: 4 }
        );
      })
  );

  test.effect(
    "turns empty and multiple producer failures into invariant defects",
    () =>
      Effect.gen(function* () {
        const invalidCauses = [
          {
            cause: Cause.empty,
            message: "Docs route failure contained no expected error",
          },
          {
            cause: Cause.combine(
              Cause.fail(
                new DocsSourceError({
                  message: "First source failure",
                  operation: "getPage",
                })
              ),
              Cause.fail(
                new DocsSourceError({
                  message: "Second source failure",
                  operation: "getPage",
                })
              )
            ),
            message: "Docs route failure contained multiple expected errors",
          },
        ];

        yield* Effect.forEach(
          invalidCauses,
          ({ cause, message }) =>
            Effect.gen(function* () {
              const exit = yield* Effect.exit(
                docsHomeRouteBoundary.encodeExit(Effect.failCause(cause))
              );
              expect(Exit.isFailure(exit)).toBe(true);
              if (Exit.isFailure(exit)) {
                expect(Cause.hasDies(exit.cause)).toBe(true);
                expect(Cause.pretty(exit.cause)).toContain(message);
              }
            }),
          { concurrency: 4 }
        );
      })
  );

  test.effect(
    "rejects decoded empty, multiple, interrupted and defect representations",
    () =>
      Effect.gen(function* () {
        const decodedInvalidRepresentations = yield* Effect.all([
          encodeHomeExit(Exit.failCause(Cause.empty)),
          encodeHomeExit(
            Exit.failCause(
              Cause.combine(
                Cause.fail(
                  new DocsSourceError({
                    message: "First source failure",
                    operation: "getPage",
                  })
                ),
                Cause.fail(
                  new DocsSourceError({
                    message: "Second source failure",
                    operation: "getPage",
                  })
                )
              )
            )
          ),
          encodeHomeExit(Exit.failCause(Cause.interrupt(103))),
          encodeUntrustedDefectExit(
            Exit.failCause(Cause.die(new Error("untrusted defect")))
          ),
        ]);

        yield* Effect.forEach(decodedInvalidRepresentations, (encoded) =>
          Effect.sync(() => {
            const result = docsHomeRouteBoundary.restore(encoded);
            expect(Result.isFailure(result)).toBe(true);
            if (Result.isFailure(result)) {
              expect(Schema.is(DocsRouteTransportError)(result.failure)).toBe(
                true
              );
            }
          })
        );
      })
  );
});

import { DocsSourceError } from "@taxkit/docs-content/errors";
import { DocsContentPage, DocsNavigation } from "@taxkit/docs-content/schemas";
import {
  Array,
  Cause,
  Effect,
  Exit,
  Match,
  Result,
  Schema,
  SchemaIssue,
  pipe,
} from "effect";

import { DocsContentPreloadError, DocsRouteTransportError } from "./errors";

type UntrustedRouteTransport = typeof Schema.Unknown.Type;

type SyncSchema = Schema.Top & {
  readonly DecodingServices: never;
  readonly EncodingServices: never;
};

type RouteBoundarySchemas<
  Success extends SyncSchema,
  Failure extends SyncSchema,
> = Readonly<{
  error: Failure;
  success: Success;
}>;

const DocsHomeLoaderSuccess = Schema.Struct({
  navigation: DocsNavigation,
  pages: Schema.Array(DocsContentPage),
});

const DocsPageLoaderSuccess = Schema.Struct({
  navigation: DocsNavigation,
  page: DocsContentPage,
});

const DocsLoaderError = Schema.Union([
  DocsContentPreloadError,
  DocsSourceError,
]);

const createRouteBoundary = <
  Success extends SyncSchema,
  Failure extends SyncSchema,
>(
  schemas: RouteBoundarySchemas<Success, Failure>
) => {
  const codec = Schema.toCodecJson(
    Schema.Exit(schemas.success, schemas.error, Schema.Never)
  );
  const encode = Schema.encodeEffect(codec);
  const formatSchemaIssue = SchemaIssue.makeFormatterDefault();

  return {
    codec,
    encodeExit: <R>(
      program: Effect.Effect<Success["Type"], Failure["Type"], R>
    ) =>
      Effect.exit(program).pipe(
        Effect.flatMap((exit) =>
          Match.value(exit).pipe(
            Match.when(Exit.isSuccess, (successExit) =>
              encode(successExit).pipe(Effect.orDie)
            ),
            Match.orElse((failureExit) =>
              Match.value(failureExit.cause).pipe(
                Match.when(Cause.hasDies, (cause) => Effect.failCause(cause)),
                Match.when(Cause.hasInterrupts, (cause) =>
                  Effect.failCause(cause)
                ),
                Match.orElse((cause) =>
                  pipe(
                    cause.reasons,
                    Array.filter(Cause.isFailReason),
                    Array.matchLeft({
                      onEmpty: () =>
                        Effect.die(
                          new Error(
                            "Docs route failure contained no expected error"
                          )
                        ),
                      onNonEmpty: (_failure, additionalFailures) =>
                        pipe(
                          additionalFailures,
                          Array.match({
                            onEmpty: () =>
                              encode(failureExit).pipe(Effect.orDie),
                            onNonEmpty: () =>
                              Effect.die(
                                new Error(
                                  "Docs route failure contained multiple expected errors"
                                )
                              ),
                          })
                        ),
                    })
                  )
                )
              )
            )
          )
        )
      ),
    restore: (encoded: UntrustedRouteTransport) =>
      Schema.decodeUnknownResult(codec)(encoded).pipe(
        Result.mapError(
          (error) =>
            new DocsRouteTransportError({
              message: formatSchemaIssue(error.issue),
            })
        ),
        Result.flatMap((exit) =>
          Match.value(exit).pipe(
            Match.when(Exit.isSuccess, ({ value }) => Result.succeed(value)),
            Match.orElse(({ cause }) =>
              Match.value(cause).pipe(
                Match.when(Cause.hasDies, () =>
                  Result.fail(
                    new DocsRouteTransportError({
                      message: "Decoded loader failure contained a defect",
                    })
                  )
                ),
                Match.when(Cause.hasInterrupts, () =>
                  Result.fail(
                    new DocsRouteTransportError({
                      message:
                        "Decoded loader failure contained an interruption",
                    })
                  )
                ),
                Match.orElse((expectedCause) =>
                  pipe(
                    expectedCause.reasons,
                    Array.filter(Cause.isFailReason),
                    Array.matchLeft({
                      onEmpty: () =>
                        Result.fail(
                          new DocsRouteTransportError({
                            message:
                              "Decoded loader failure contained no expected error",
                          })
                        ),
                      onNonEmpty: (failure, additionalFailures) =>
                        pipe(
                          additionalFailures,
                          Array.match({
                            onEmpty: () => Result.fail(failure.error),
                            onNonEmpty: () =>
                              Result.fail(
                                new DocsRouteTransportError({
                                  message:
                                    "Decoded loader failure contained multiple expected errors",
                                })
                              ),
                          })
                        ),
                    })
                  )
                )
              )
            )
          )
        )
      ),
  };
};

