import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import type {
  DocsContentPage,
  DocsNavigation,
} from "@taxkit/docs-content/schemas";
import { Array, Result, pipe } from "effect";

import {
  DocsRecoverableError,
  DocsRouteError,
  DocsRoutePending,
} from "#/components/docs-route-states";
import { loadDocsHome } from "#/lib/docs/loaders";
import { docsHomeRouteBoundary } from "#/lib/docs/route-boundary";
import { requestDocsNavigationFocus } from "#/lib/navigation-focus";

const DocsHomeFailure = ({ onRetry }: { readonly onRetry: () => void }) => (
  <DocsRecoverableError
    message="The documentation source could not be loaded."
    onRetry={onRetry}
  />
);

const DocsHomeContent = ({
  navigation,
  pages,
}: Readonly<{
  navigation: DocsNavigation;
  pages: readonly DocsContentPage[];
}>) => (
  <section className="docs-home">
    <div className="docs-home__intro">
      <p className="docs-kicker">TaxKit docs</p>
      <h1 id="docs-page-heading" tabIndex={-1}>
        Open-source tax engine, API and SDK documentation
      </h1>
      <p>
        Start with the integration path, then move through SDK, API, guides,
        concepts, contribution notes and reference material.
      </p>
    </div>
    <nav aria-label="Primary documentation" className="docs-section-list">
      {pipe(
        navigation.primaryNavigation,
        Array.map((section) => (
          <Link
            className="docs-section-card"
            key={section.path}
            onClick={requestDocsNavigationFocus}
            params={{ _splat: section.path.slice(1) }}
            to="/$"
          >
            <span>{section.title}</span>
            <small>{section.primaryReader}</small>
          </Link>
        ))
      )}
    </nav>
    <p className="docs-count">{pages.length} documentation pages loaded.</p>
  </section>
);

export const Route = createFileRoute("/")({
  component: function DocsHomeRoute() {
    const loaderData = Route.useLoaderData();
    const router = useRouter();
    const routeResult = docsHomeRouteBoundary.restore(loaderData);

    return Result.match(routeResult, {
      onFailure: () => (
        <DocsHomeFailure
          onRetry={() => {
            void router.invalidate();
          }}
        />
      ),
      onSuccess: ({ navigation, pages }) => (
        <DocsHomeContent navigation={navigation} pages={pages} />
      ),
    });
  },
  errorComponent: DocsRouteError,
  loader: loadDocsHome,
  pendingComponent: DocsRoutePending,
  pendingMs: 150,
});

import {
  createStartHandler,
  defaultStreamHandler,
} from "@tanstack/react-start/server";
import { Array, Effect, Schema } from "effect";

import {
  DocsRuntimeProbeSnapshot,
  readDocsRuntimeProbe,
} from "./lib/runtime-factory.server";
import { docsRuntime } from "./lib/runtime.server";

const startHandler = createStartHandler(defaultStreamHandler);
const runtimeProofRequestHeader = "x-taxkit-docs-runtime-proof";
const runtimeProofResponseHeader = "x-taxkit-docs-runtime-constructions";
const runtimeProofIsolateHeader = "x-taxkit-docs-runtime-isolate";

export default {
  fetch: (request: Request) =>
    Effect.runPromise(
      Effect.gen(function* () {
        // The host permits either a Response or Promise; normalise its result here.
        // Unexpected framework rejection remains a defect.
        const response = yield* Effect.promise(() =>
          Promise.resolve(startHandler(request))
        );
        if (
          request.headers.get(runtimeProofRequestHeader) !==
          "construction-count"
        ) {
          return response;
        }
        // Ordinary host responses do not initialise documentation services.
        const context = yield* docsRuntime.contextEffect;
        const probe = yield* readDocsRuntimeProbe.pipe(
          Effect.provide(context),
          Effect.flatMap(Schema.encodeEffect(DocsRuntimeProbeSnapshot))
        );
        // Preserve unrelated host headers and replace only the two proof headers.
        const headers = new Headers([
          ...Array.filter(
            Array.fromIterable(response.headers),
            ([name]) =>
              name !== runtimeProofResponseHeader &&
              name !== runtimeProofIsolateHeader
          ),
          [runtimeProofResponseHeader, String(probe.constructions)],
          [runtimeProofIsolateHeader, probe.isolateId],
        ]);
        return new Response(response.body, {
          headers,
          status: response.status,
          statusText: response.statusText,
        });
      }),
      { signal: request.signal }
    ),
};

